// Modelo simplificado: cada servidor atiende de a un pedido por vez y hace cola.
const servicio = { A: 20, B: 200 };          // milisegundos por pedido
const N = 100, cadaMs = 10;                  // 100 pedidos, uno cada 10 ms (100 por segundo)

function simular(nombre, elegir) {
  const libre = { A: 0, B: 0 };              // instante en que cada servidor termina lo que tiene
  const termina = { A: [], B: [] };          // fin de cada pedido aceptado
  const cuenta = { A: 0, B: 0 };
  let esperaMax = 0, finUltimo = 0;
  for (let i = 0; i < N; i++) {
    const t = i * cadaMs;
    const enCurso = (s) => termina[s].filter((f) => f > t).length;
    const s = elegir(i, enCurso);
    const inicio = Math.max(t, libre[s]);
    libre[s] = inicio + servicio[s];
    termina[s].push(libre[s]);
    cuenta[s]++;
    esperaMax = Math.max(esperaMax, libre[s] - t);
    finUltimo = Math.max(finUltimo, libre[s]);
  }
  console.log(nombre.padEnd(18), 'A:', String(cuenta.A).padStart(3), ' B:', String(cuenta.B).padStart(3),
    ' peor respuesta:', esperaMax, 'ms  termina a los', finUltimo, 'ms');
}
simular('round robin', (i) => (i % 2 === 0 ? 'A' : 'B'));
simular('menos conexiones', (i, enCurso) => (enCurso('A') <= enCurso('B') ? 'A' : 'B'));
